if (e && e.target.classList.contains('active')) {
  const state = $app.ServiceRef.dispatch({}, { actionType: 'state' });
  const count = state.count + 1;
  $app.ServiceRef.dispatch({ count, active: -1 }, { actionType: 'computed', name: ['count', 'active'] });
}

pageSchema.worker:
(e) => {
  if (!e.data.start) {
    return Promise.resolve({ active: -1 });
  }
  const active = Math.floor(Math.random() * 4);
  return Promise.resolve({
    date: Date.now(),
    active,
  });
}

pageSchema.innerStyle:
.container {
  width: 200px;
  height: 120px;
  display: flex;
  flex-direction: row;
  gap: 20px;
}
.item {
  width: 40px;
  height: 10px;
  margin-top: auto;
  background-color: var(--el-color-success);
  &.active {
    height: 120px;
    animation: ddd 0.2s ease-in-out;
  }
}

@keyframes ddd {
  from {
    height: 10px;
  }
  to {
    height: 120px;
  }
}
